<?php
namespace Tests\Feature;use App\Jobs\ProcessMediaAsset;use App\Models\{Group,UploadBatch,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\{Hash,Queue,Storage};use Tests\TestCase;
class BackgroundProcessingTest extends TestCase {use RefreshDatabase;protected function setUp():void{parent::setUp();config(['media.disk'=>'private_local','queue.default'=>'sync']);Storage::fake('private_local');}private function owner(string$email):array{$u=User::create(['name'=>'Owner','email'=>$email,'password'=>Hash::make('x'),'status'=>'active','account_type'=>'photographer']);$g=Group::create(['name'=>'Event','creator_id'=>$u->id]);$g->members()->attach($u->id,['role'=>'admin','membership_status'=>'active','access_type'=>'full_access']);return[$u,$g];}
 public function test_original_is_stored_and_processing_is_dispatched():void{Queue::fake();[$u,$g]=$this->owner('owner@example.com');$this->actingAs($u)->postJson(route('photos.store',$g),['photos'=>[UploadedFile::fake()->image('one.jpg')]])->assertOk()->assertJsonStructure(['batch_uuid','state']);$batch=UploadBatch::firstOrFail();$this->assertSame('queued',$batch->fresh()->state);$asset=$batch->files()->firstOrFail()->asset;Storage::disk('private_local')->assertExists($asset->original_object_key);$this->assertCount(1,$asset->variants);Queue::assertPushed(ProcessMediaAsset::class,1);}
 public function test_progress_is_not_visible_across_accounts():void{[$owner,$group]=$this->owner('owner@example.com');[$other]=$this->owner('other@example.com');$batch=UploadBatch::create(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'group_id'=>$group->id,'user_id'=>$owner->id,'total_files'=>1]);$this->actingAs($other)->getJson(route('processing.show',$batch))->assertForbidden();}
 public function test_cancel_and_retry_require_owned_batch():void{[$owner,$group]=$this->owner('owner@example.com');$batch=UploadBatch::create(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'group_id'=>$group->id,'user_id'=>$owner->id,'total_files'=>1]);$this->actingAs($owner)->postJson(route('processing.cancel',$batch))->assertOk()->assertJson(['state'=>'cancelled']);$this->postJson(route('processing.retry',$batch))->assertStatus(409);}
}
